-- Minimal synthetic local schema; not production schema or hosted acceptance.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$;
CREATE TYPE public.event_type AS ENUM('game','training','social');
CREATE TYPE public.app_role AS ENUM('app_admin','club_admin','league_admin','player','parent');
CREATE TABLE public.competitions(id uuid PRIMARY KEY,organizer_club_id uuid);
GRANT ALL ON public.competitions TO service_role;
CREATE TABLE public.teams(id uuid PRIMARY KEY,club_id uuid,is_archived boolean,deleted_at timestamptz);
GRANT ALL ON public.teams TO service_role;
CREATE TABLE public.competition_roles(competition_id uuid,user_id uuid,role text);
GRANT ALL ON public.competition_roles TO service_role;
CREATE TABLE public.competition_entries(competition_id uuid,team_id uuid,status text);
GRANT ALL ON public.competition_entries TO service_role;
CREATE TABLE public.team_captains(team_id uuid,user_id uuid);
GRANT ALL ON public.team_captains TO service_role;
CREATE TABLE public.user_roles(user_id uuid,club_id uuid,team_id uuid,role public.app_role);
GRANT ALL ON public.user_roles TO service_role;
CREATE TABLE public.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid,team_id uuid,title text,description text,event_date timestamptz,end_time timestamptz,location text,location_name text,type public.event_type,created_by uuid,competition_id uuid,reminder_hours_before integer,notify_suppressed boolean,duty_team_id uuid);
GRANT ALL ON public.events TO service_role;
CREATE TABLE public.notifications(user_id uuid,type text,message text,related_id uuid,club_id uuid,skip_push boolean,dedupe_key text UNIQUE);
GRANT ALL ON public.notifications TO service_role;
CREATE TABLE public.club_news(id uuid PRIMARY KEY,club_id uuid,author_id uuid,title text,is_important boolean,is_published boolean,published_at timestamptz,target_competition_id uuid,target_mini_league_id uuid,target_team_ids uuid[]);
GRANT ALL ON public.club_news TO service_role;
CREATE TABLE public.mini_league_players(mini_league_id uuid,parent_user_id uuid);
GRANT ALL ON public.mini_league_players TO service_role;
CREATE TABLE public.mini_league_admins(mini_league_id uuid,user_id uuid);
GRANT ALL ON public.mini_league_admins TO service_role;
CREATE FUNCTION public.is_competition_role_admin(u uuid,c uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM competition_roles WHERE user_id=u AND competition_id=c AND role IN('owner','admin')) $$;
CREATE FUNCTION public.is_club_member(u uuid,c uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND club_id=c) $$;
CREATE FUNCTION public.is_club_admin_for(c uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND club_id=c AND role='club_admin') $$;
CREATE FUNCTION public.has_role(u uuid,r public.app_role) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND role=r) $$;
CREATE FUNCTION public.can_create_competition_event(u uuid,c uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT public.is_competition_role_admin(u,c) $$;
CREATE FUNCTION public.competition_event_audience(c uuid) RETURNS TABLE(user_id uuid,club_id uuid) LANGUAGE sql AS $$ SELECT DISTINCT ur.user_id,ur.club_id FROM user_roles ur JOIN competition_entries ce ON ce.team_id=ur.team_id WHERE ce.competition_id=c AND ce.status='accepted' $$;
CREATE TABLE public.photos(competition_id uuid);
GRANT ALL ON public.photos TO service_role;
CREATE FUNCTION public.synthetic_trigger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END; $$;
CREATE TRIGGER trg_photos_mirror_competition_vault AFTER INSERT ON public.photos FOR EACH ROW EXECUTE FUNCTION public.synthetic_trigger();
CREATE TABLE public.competition_role_links(id uuid);
GRANT ALL ON public.competition_role_links TO service_role;
CREATE FUNCTION public.accept_competition_role_link(text) RETURNS text LANGUAGE sql AS $$ SELECT 'synthetic' $$;
CREATE FUNCTION public.get_competition_role_link_status(text) RETURNS text LANGUAGE sql AS $$ SELECT 'synthetic' $$;
